import React, { useState, useEffect } from "react";
import axios from "axios";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import SupervisorSidebar from "../components/SupervisorSidebar";

const ProvideFeedback = () => {
  const [feedback, setFeedback] = useState("");
  const [selectedTask, setSelectedTask] = useState(null);
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  const facultyId = "YOUR_FACULTY_ID"; // Replace with real faculty ID

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [docRes, milestoneRes] = await Promise.all([
          axios.get("http://localhost:5000/api/document"),
          axios.get("http://localhost:5000/api/milestone"),
        ]);

        const approvedDocs = docRes.data
          .filter(doc => doc.status === "approved" || doc.status === "rejected")
          .map(doc => ({
            id: doc._id,
            title: doc.title,
            description: `Document Type: ${doc.documentType}`,
            group: doc.projectID,
            type: "document",
          }));

        const milestones = milestoneRes.data.map(ms => ({
          id: ms._id,
          title: ms.title,
          description: `Due: ${new Date(ms.dueDate).toLocaleDateString()}`,
          group: ms.projectID,
          type: "milestone",
        }));

        setTasks([...approvedDocs, ...milestones]);
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleFeedbackSubmit = async (e) => {
    e.preventDefault();
    if (!selectedTask) return;

    const payload = {
      facultyId,
      groupId: selectedTask.group,
      content: feedback,
      date: new Date(),
      type: selectedTask.type,
      ...(selectedTask.type === "document"
        ? { documentId: selectedTask.id }
        : { milestoneId: selectedTask.id }),
    };

    try {
      const feedbackRes = await axios.get("http://localhost:5000/api/feedback");
      const existing = feedbackRes.data.find(fb =>
        fb.groupId === selectedTask.group &&
        fb.type === selectedTask.type &&
        ((fb.documentId === selectedTask.id && selectedTask.type === "document") ||
         (fb.milestoneId === selectedTask.id && selectedTask.type === "milestone"))
      );

      if (existing) {
        await axios.patch(`http://localhost:5000/api/feedback/${existing._id}`, payload);
      } else {
        await axios.post("http://localhost:5000/api/feedback", payload);
      }

      alert("Feedback submitted successfully!");
      setFeedback("");
      setSelectedTask(null);
    } catch (error) {
      console.error("Failed to submit feedback:", error);
      alert("An error occurred while submitting feedback.");
    }
  };

  return (
    <div className="feedback-container">
      <Navbar />
      <div className="dashboard-layout">
        <SupervisorSidebar />

        <main className="feedback-main">
          <h1>Provide Feedback</h1>

          <div className="task-section">
            <h2>Submitted Tasks</h2>

            {loading ? (
              <p>Loading tasks...</p>
            ) : tasks.length === 0 ? (
              <p
                style={{
                  fontSize: "1.1rem",
                  color: "#777",
                  padding: "20px",
                  textAlign: "center",
                }}
              >
                No approved/rejected documents or milestones found.
              </p>
            ) : (
              <div className="task-list">
                {tasks.map(task => (
                  <div
                    key={task.id}
                    className={`task-card ${selectedTask?.id === task.id ? "selected" : ""}`}
                    onClick={() => setSelectedTask(task)}
                  >
                    <h3>{task.title}</h3>
                    <p><strong>Group:</strong> {task.group}</p>
                    <p>{task.description}</p>
                    <p><strong>Type:</strong> {task.type.charAt(0).toUpperCase() + task.type.slice(1)}</p>
                  </div>
                ))}
              </div>
            )}
          </div>

          {selectedTask && (
            <div className="feedback-form-section">
              <h2>Provide Feedback for: {selectedTask.title}</h2>
              <form onSubmit={handleFeedbackSubmit} className="feedback-form">
                <textarea
                  placeholder="Write your feedback here..."
                  value={feedback}
                  onChange={(e) => setFeedback(e.target.value)}
                  required
                />
                <button type="submit">Submit Feedback</button>
              </form>
            </div>
          )}
        </main>
      </div>
      <Footer />
    </div>
  );
};

export default ProvideFeedback;
